  {"titulo": "Cierre de la aplicación con cambios pendientes", "tipo": "borde", "dado": ["que marqué un producto como agotado sin señal"], "cuando": "cierro la aplicación o reinicio mi celular y luego la abro de nuevo", "entonces": ["el producto sigue mostrándose como agotado y pendiente de sincronizar", "el cambio no se pierde"]},
  {"titulo": "Volver a marcar el producto como disponible", "tipo": "exito", "dado": ["que tengo un producto marcado como agotado", "que mi celular tiene conexión a internet"], "cuando": "marco el producto como \"Disponible\"", "entonces": ["el producto vuelve a mostrarse disponible para los clientes"]}
]}

