{"historia_id": "H6", "invest_ok": true, "preguntas": ["¿Cómo se devuelve el dinero al cliente: automáticamente a su Yape o Plin, o mediante un proceso manual? ¿En cuánto tiempo?", "¿Hasta qué momento puede el comerciante rechazar su parte (por ejemplo, antes de marcarla como lista)?", "¿Se devuelve también la parte proporcional del costo de delivery si el pedido queda sin productos?", "¿Es obligatorio indicar un motivo de rechazo?"], "escenarios": [
  {"titulo": "Rechazar mi parte de un pedido pagado", "tipo": "exito", "dado": ["que soy un comerciante con sesión iniciada", "que existe un pedido pagado con productos de mi puesto y de otro puesto", "que mi parte aún no está marcada como lista"], "cuando": "rechazo mi parte del pedido indicando que ya no tengo el producto", "entonces": ["mi parte del pedido queda con estado \"Rechazada\"", "se calcula el reembolso solo con el monto de los productos de mi puesto", "la parte del otro puesto sigue su curso sin cambios", "el cliente recibe una notificación con el detalle de lo rechazado y lo que se le devolverá"]},
  {"titulo": "Reembolso solo por la parte rechazada", "tipo": "exito", "dado": ["que un cliente pagó S/ 50 en total, de los cuales S/ 20 corresponden a mi puesto"], "cuando": "rechazo mi parte del pedido", "entonces": ["se devuelven al cliente S/ 20 por el medio de pago original", "los S/ 30 restantes no se devuelven y siguen asignados al otro puesto"]},
  {"titulo": "Rechazo de un solo producto de mi parte", "tipo": "exito", "dado": ["que mi parte del pedido incluye dos productos", "que solo me falta uno de ellos"], "cuando": "rechazo únicamente ese producto", "entonces": ["se reembolsa solo el monto de ese producto", "el otro producto de mi puesto se mantiene en el pedido para prepararse"]},
  {"titulo": "Rechazo de una parte ya marcada como lista", "tipo": "error", "dado": ["que mi parte del pedido ya fue marcada como lista o entregada"], "cuando": "intento rechazarla", "entonces": ["el sistema no permite el rechazo", "veo un mensaje que explica que la parte ya no puede rechazarse"]},
  {"titulo": "Rechazo de un pedido que no es de mi puesto", "tipo": "error", "dado": ["que existe un pedido pagado sin productos de mi puesto"], "cuando": "intento rechazar una parte de ese pedido", "entonces": ["el sistema no me muestra ni permite esa acción", "no se modifica el pedido"]},
  {"titulo": "Falla del reembolso", "tipo": "error", "dado": ["que rechacé mi parte de un pedido"], "cuando": "el reembolso al cliente no puede procesarse", "entonces": ["el reembolso queda registrado como pendiente", "el sistema reintenta o lo deriva a revisión manual", "el cliente es informado de que su devolución está en proceso"]},
  {"titulo": "Todos los puestos rechazan su parte", "tipo": "borde", "dado": ["que un pedido incluye productos de dos puestos"], "cuando": "ambos comerciantes rechazan su parte", "entonces": ["el pedido pasa a estado \"Cancelado\"", "se reembolsa al cliente el total de los productos", "se define la devolución del costo de delivery según la regla del negocio"]},
  {"titulo": "Doble rechazo de la misma parte", "tipo": "borde", "dado": ["que ya rechacé mi parte de un pedido"], "cuando": "envío nuevamente el rechazo, por ejemplo por un doble toque", "entonces": ["el reembolso se genera una sola vez", "el estado de mi parte permanece como \"Rechazada\""]}
]}

